{
  "sop_id": "SOP-015",
  "title": "Invoice verification",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Verify vendor GSTIN and PAN, check for duplicates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Perform three-way match (invoice vs PO vs GRN)",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Calculate GST input credit and TDS",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Account for advances or other deductions",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Prepare payment voucher",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Submit payment voucher",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S8",
      "name": "Wait for Stores/Operations confirmation if GRN/completion certificate pending",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "A1",
      "name": "Incharge verification and approval or rejection",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rework after rejection",
      "role": "Executor",
      "type": "rework"
    },
    {
      "step_id": "A2",
      "name": "Lead approval (if required)",
      "role": "Lead",
      "type": "approval"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "invoice outside tolerance (price >2% off, quantity variance) or >10 lakh, or foreign-currency invoice"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Stores or Operations",
      "item": "GRN or completion certificate confirmation",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
